$ cat Safe.java
public class Safe {
    static long sink;
    // int 카운터 루프 — 컴파일러가 폴을 빼는 자리
    static long counted(int n) {
        long s = 0;
        for (int i = 0; i < n; i++) s += i ^ (i >> 3);
        return s;
    }
    public static void main(String[] a) throws Exception {
        for (int r = 0; r < 6; r++) sink = counted(Integer.MAX_VALUE - 1);
    }
}

# --- 1) 기본값 확인 ---

